// nppiCrossCorr* / nppiSqrDistance* family executor (package p1.8).
//
// Host-visible surface (safe for plain .cpp translation units): the entry-point
// template is declared here and defined + explicitly instantiated in
// nppi_crosscorr_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_crosscorr_*.json and
// nppi_sqrdistance_*.json); the three GetAdvancedScratchBufferSize entry
// points (int* and size_t* overloads) are hand-written in
// nppi_crosscorr_scratch_size.cpp.
//
// Semantics (baseline NVIDIA NPP 13.4 on the RTX 5090, validated by probes and
// differential tests):
//   * Template matching of oTplRoiSize against oSrcRoiSize, one independent
//     computation per color channel (interleaved R layouts).  AC4 ignores the
//     src/tpl alpha channel and leaves the dst alpha channel untouched.
//   * Output geometry (dst is always a full image, never a scalar):
//       Full : (Ws + tw - 1) x (Hs + th - 1), dst(c, r) window origin
//              (c - (tw - 1), r - (th - 1))   [anchor = template bottom right]
//       Same : Ws x Hs,                        dst(c, r) window origin
//              (c - tw/2, r - th/2)            [C integer division]
//       Valid: (Ws - tw + 1) x (Hs - th + 1),  dst(c, r) window origin (c, r)
//     Source samples outside the ROI contribute w = 0 (zero padding); the
//     template is always read in full.
//   * Ops (all accumulate in double precision):
//       Plain     : dst = sum(w * t)                      (raw dot product)
//       Norm      : dst = Rst / sqrt(Rss * Rtt) with Rst = sum(w * t),
//                   Rss = sum(w * w) (padded window), Rtt = sum(t * t) (full
//                   template).  0/0 -> NaN, x/0 with x != 0 impossible, so
//                   Norm never produces +-inf.
//       NormLevel : zero-mean normalized (ZNCC).  N = tw * th always (padded
//                   positions included), Ms = Sw/N, Mt = St/N,
//                   num = Rst - Ms*St - Mt*Sw + N*Ms*Mt,
//                   varW = Rw + N*Ms^2 - 2*Ms*Sw, varT = Rtt - St^2/N,
//                   dst = num / sqrt(varW * varT).  varW * varT == 0 (constant
//                   window or constant template) writes the sentinel
//                   FLT_MAX for every dst type with <= 4-byte elements
//                   (including 8u Sfs -> 255) and DBL_MAX for 64f dst, to
//                   EVERY dst pixel.
//       NormLevelAdvanced: same math as NormLevel, scratch supplied by the
//                   caller through nppiCrossCorr*NormLevel_GetAdvancedScratch-
//                   BufferSize (size = 16 + 2 * dstArea * sizeof(D) * Channels,
//                   dstArea = (Ws+tw-1)*(Hs+th-1) for Full, Ws*Hs for Same and
//                   Valid).
//       SqrDistance: dst = sum((w - t)^2) / sqrt(Rss * Rtt), numerator over
//                   all tw * th padded positions.  Zero src (nonzero tpl) ->
//                   +inf, zero tpl (nonzero src) -> +inf, zero both -> NaN.
//   * 8u dst (Sfs variants): dst = sat[0,255](trunc(value) * 2^-nScaleFactor)
//     with the final store truncating fractional results (5090-measured:
//     fractional gamma stays 0 for every scale factor, gamma = 1 gives 1 at
//     sf = 0 and 255 at sf = -8).  NaN -> 0, +-inf / FLT_MAX -> 255.
//   * Validation order (5090-measured, every step returns before the next):
//       1. [Advanced only] null pDeviceBuffer or pAdvancedScratchBuffer
//          -> NPP_NULL_POINTER_ERROR (before any ROI check)
//       2. null pSrc                  -> NPP_NULL_POINTER_ERROR
//       3. src ROI zero-sized         -> NPP_NO_ERROR, nothing written
//          src ROI negative           -> NPP_SIZE_ERROR
//       4. tpl ROI likewise (src fully checked first)
//       5. src step: (uint32)nSrcStep < Ws * Channels * sizeof(S)
//          -> NPP_STEP_ERROR; nSrcStep % (sizeof(S) * 2^v2(Channels)) != 0
//          -> NPP_NOT_EVEN_STEP_ERROR (size check first; negative steps pass
//          the size check through unsigned wraparound).  The step is checked
//          BEFORE the pTpl/pDst pointers (null dst + bad src step -> -16).
//       6. null pTpl or pDst          -> NPP_NULL_POINTER_ERROR
//       7. [Valid only] dstW = Ws - tw + 1, dstH = Hs - th + 1; a negative
//          dimension -> NPP_SIZE_ERROR; a zero dimension -> NPP_NO_ERROR
//          (nothing written, tpl/dst steps are NOT validated in that case)
//       8. dst step checks like the src step, against dstW * Channels *
//          sizeof(D) (dst is fully validated before the tpl step)
//       9. tpl step checks like the src step, against tw * Channels * sizeof(S)
//      10. [NormLevel non-Advanced only] null pDeviceBuffer
//          -> NPP_NULL_POINTER_ERROR (before the tpl>src geometry error)
//      11. [Full/Same only] tw > Ws or th > Hs -> NPP_SIZE_ERROR (a single
//          violating dimension suffices; equal dims are ok)
//      12. launch the kernel
//   * pDeviceBuffer (NormLevel) and pAdvancedScratchBuffer are scratch only
//     and are never dereferenced by this implementation; exact sizes are not
//     a contract, only that the helper-reported sizes are sufficient.
#ifndef NPPI_CROSSCORR_EXECUTOR_H
#define NPPI_CROSSCORR_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace statistics {

enum class CrossCorrMode { Full, Same, Valid };

enum class CrossCorrOp {
  Plain,             // nppiCrossCorrValid
  Norm,              // nppiCrossCorr*_Norm / nppiSqrDistance*_Norm (Sqr = true)
  NormLevel,         // nppiCrossCorr*_NormLevel
  NormLevelAdvanced, // nppiCrossCorr*_NormLevelAdvanced
  SqrDistance,       // nppiSqrDistance*_Norm
};

// Template matching executor.  S = source/template element type, D = dst
// element type, Channels = packed channels per pixel, AlphaPreserve selects
// AC4 (processes Channels-1 channels and leaves dst alpha untouched).
// nScaleFactor is only used when D is an integral type (Sfs variants); pass 0
// otherwise.  pDeviceBuffer is required by the API for NormLevel /
// NormLevelAdvanced (validated for null but not dereferenced);
// pAdvancedScratchBuffer likewise for NormLevelAdvanced only.
template <typename S, typename D, int Channels, bool AlphaPreserve, CrossCorrMode M, CrossCorrOp Op>
NppStatus runCrossCorr(const S *pSrc, int nSrcStep, NppiSize oSrcRoiSize, const S *pTpl, int nTplStep,
                       NppiSize oTplRoiSize, D *pDst, int nDstStep, int nScaleFactor, Npp8u *pDeviceBuffer,
                       Npp8u *pAdvancedScratchBuffer, cudaStream_t stream);

}  // namespace statistics
}  // namespace nppi

#endif  // NPPI_CROSSCORR_EXECUTOR_H
